import * as E from './engine.js';
import {store,quote} from './storage.js';
import {excelReport, reportRows} from './reports.js';
import {Cloud, canonical} from './cloud.js';
const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), money=E.money, uid=E.id, now=()=>new Date().toISOString(), today=E.today, n=E.number;
let state,loadFailed=false;try{state=E.validateBackup(store.load())}catch(err){alert('Não foi possível carregar seus dados. O armazenamento original foi preservado. '+err.message);state=E.empty();loadFailed=true;}let tab='overview', filter='all', analysisType='all';
let storedAtRender=canonical(state);
const cloud=new Cloud({read:()=>{if(loadFailed)throw Error('Restaure um backup válido.');return E.validateBackup(store.load())},validate:E.validateBackup,isEmpty:x=>canonical(x)===canonical(E.empty()),canApply:()=>!loadFailed&&!$('#modal').open,apply:(payload,preserve)=>{if(preserve){localStorage.setItem('ptp-cloud-recovery-v1',JSON.stringify(store.load()))}store.save(payload);state=E.validateBackup(store.load());storedAtRender=canonical(state);render()},status:msg=>{const badge=$('#saveStatus');if(badge)badge.textContent=msg;const line=$('#cloudStatus');if(line)line.textContent=msg;const choices=$('#cloudChoices');if(choices)choices.innerHTML=cloudChoices()}});
const methods=['Crédito','Débito','Dinheiro','Pix'];
const svgIcon=(path)=>`<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${path}</svg>`;const nav=[['home',svgIcon('<path d="m3 10 9-7 9 7v10H15v-6H9v6H3Z"/>'),'Início'],['trips',svgIcon('<path d="M21 3 9.5 14.5"/><path d="M21 3 14 21l-4.5-6.5L3 10z"/>'),'Viagens'],['wallet',svgIcon('<path d="M12 2v20M17 6H9a4 4 0 0 0 0 8h6a4 4 0 0 1 0 8H6" transform="translate(0 -1)"/>'),'Carteira'],['analysis',svgIcon('<path d="M3 3v18h18M7 17v-5M12 17V8M17 17V5"/>'),'Análises'],['profile',svgIcon('<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2Z"/>'),'Perfil']];
const btn=(label,action,id='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" data-id="${esc(id)}">${esc(label)}</button>`;
const options=(arr,v)=>arr.map(x=>{let [a,b]=Array.isArray(x)?x:[x,x];return `<option value="${esc(a)}" ${String(a)===String(v)?'selected':''}>${esc(b)}</option>`}).join('');
const field=(label,key,value='',type='text',attrs='')=>`<label for="f-${key}">${esc(label)}</label><input id="f-${key}" name="${key}" type="${type}" value="${esc(value)}" ${attrs}>`;
const select=(label,key,arr,v)=>`<label for="f-${key}">${esc(label)}</label><select id="f-${key}" name="${key}">${options(arr,v)}</select>`;
const check=(label,key,value)=>`<label class="check"><input type="checkbox" name="${key}" ${value?'checked':''}>${esc(label)}</label>`;
const amount=(label,key,val,required=true)=>field(label,key,val,'number',`min="0" step="any" ${required?'required':''}`);
const metric=(label,value,cls='')=>`<div class="metric"><small>${esc(label)}</small><strong class="${cls}">${esc(value)}</strong></div>`;
const bar=p=>`<div class="bar"><span style="width:${Math.min(100,Math.max(0,p||0))}%"></span></div>`;
const empty=msg=>`<div class="empty">${esc(msg)}</div>`;
const accounts=()=>state.accounts.filter(a=>!a.archived);
const acctName=id=>state.accounts.find(a=>a.id===id)?.name??'Sem conta';
const groupName=(t,id)=>t.groups.find(g=>g.id===id)?.name??'Grupo';
const tripEntries=t=>state.entries.filter(e=>e.trip===t.id);
const activeTrip=()=>state.trips.find(t=>t.id===location.hash.slice(6));
const currency=(t,date)=>t.type==='Nacional'?'BRL':(t.destinations??[]).find(d=>d.start&&d.end&&d.start<=date&&date<=d.end)?.currency??t.currency;
function notify(msg){let t=$('#toast');t.textContent=msg;t.style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.style.display='none',3500)}
function commit(fn){if(loadFailed)throw Error('Dados originais protegidos. Restaure um backup válido antes de editar.');if(canonical(store.load())!==storedAtRender)throw Error('Outra aba alterou os dados. Recarregue antes de editar.');let next=structuredClone(state);fn(next);let l=E.ledger(next.movements,next.entries,true);for(let e of next.entries){let p=e.actual?.payments?.[0];if(p?.track){let cost=l.costs[e.id+'-0'];if(cost===undefined)throw Error('Custo da baixa indisponível.');p.brl=cost;e.actual.brl=cost}}E.validateBackup(next);store.save(next);state=next;storedAtRender=canonical(store.load());$('#saveStatus').textContent='Salvo localmente';render();if(cloud.session)cloud.schedule()}
function upsert(arr,obj){let i=arr.findIndex(x=>x.id===obj.id);if(i<0)arr.push(obj);else arr[i]=obj}
function modal(title,html,onSave,init){$('#modalTitle').textContent=title;$('#fields').innerHTML=html;let f=$('#modalForm');f.querySelector('[type=submit]').hidden=false;f.onsubmit=async ev=>{ev.preventDefault();let submit=f.querySelector('[type=submit]');submit.disabled=true;try{await onSave(Object.fromEntries(new FormData(f)),f);$('#modal').close();notify('Alterações salvas.')}catch(err){notify(err.message)}finally{submit.disabled=false}};$('#modal').showModal();init?.(f)}
$('#closeModal').onclick=$('#cancelModal').onclick=()=>$('#modal').close();
function route(path){location.hash=path;render()}
window.addEventListener('hashchange',()=>{tab='overview';filter='all';render()});
function render(){let path=location.hash.slice(1)||'home',t=activeTrip();$('#nav').innerHTML=nav.map(([key,icon,label])=>`<a href="#${key}" class="${(path===key||key==='trips'&&t)?'active':''}"><span>${icon}</span>${label}</a>`).join('');$('#title').textContent=t?t.name:({home:'Visão geral',trips:'Minhas viagens',wallet:'Minha carteira',analysis:'Perfil financeiro',profile:'Meu perfil'})[path]??'Minhas viagens';$('#app').innerHTML=t?tripView(t):({home, trips:()=>tripList(false),wallet,analysis:analysisView,profile})[path]?.()??tripList(false)}
function home(){let active=state.trips.filter(t=>t.status!=='Concluída');let upcoming=active.filter(t=>['Confirmada','Em andamento'].includes(t.status));let sums=upcoming.map(t=>E.sumTrip(t,state.entries));return `<div class="panel"><div class="eyebrow">PLANEJE COM TRANQUILIDADE</div><h2>${state.profile.name?'Olá, '+esc(state.profile.name):'Sua próxima aventura começa aqui.'}</h2><p class="muted">Organize o orçamento, acompanhe as despesas e conheça seu padrão real de viagem.</p><div class="row">${btn('+ Nova viagem','trip-new','','primary')}${!state.profile.name?btn('Configurar perfil','profile-edit'):''}</div></div><div class="grid">${metric('Viagens em aberto',String(active.length))}${metric('Orçamento confirmado',money(sums.reduce((a,x)=>a+x.limit,0)))}${metric('Realizado (confirmadas)',money(sums.reduce((a,x)=>a+x.actual,0)))}</div><section class="section">${tripList(true)}</section>`}
function tripList(short){let ts=short?state.trips.filter(t=>t.status!=='Concluída'):state.trips;return `<div class="toolbar"><h2>${short?'Próximas viagens':'Todas as viagens'}</h2>${btn('+ Nova viagem','trip-new','','primary')}</div>${ts.length?`<div class="grid">${ts.map(t=>{let x=E.sumTrip(t,state.entries);return `<article class="panel tripcard" data-action="trip-open" data-id="${esc(t.id)}"><span class="tag">${esc(t.status)} · ${esc(t.type)}</span><h2 style="margin-top:16px">${esc(t.name)}</h2><p class="muted">${esc(t.place||'Destino a definir')} · ${esc(t.start||'Sem data')}</p><small>Orçamento do meu grupo</small><div class="large">${money(x.limit)}</div>${bar(x.limit?x.actual/x.limit*100:0)}<small>Realizado: ${money(x.actual)}</small><div class="row" style="margin-top:12px">${btn('Abrir viagem','trip-open',t.id)}</div></article>`}).join('')}</div>`:empty('Nenhuma viagem cadastrada. Comece com um sonho ou uma viagem confirmada.')}`}
function tripForm(t){let old=t??{id:uid(),name:'',type:'Nacional',status:'Sonho',currency:'BRL',groups:[{id:uid(),name:'Minha família'}],people:[],methods:[],budget:0};let mine=old.mine??old.groups[0].id;modal(t?'Editar viagem':'Nova viagem',field('Nome','name',old.name,'text','required')+`<div class="formgrid">${select('Tipo','type',['Nacional','Internacional'],old.type)}${select('Situação','status',E.statuses,old.status)}</div>`+field('Destino / países','place',old.place)+`<div class="formgrid">${field('Início','start',old.start,'date')}${field('Fim','end',old.end,'date')}${select('Moeda principal do destino','currency',E.currencies,old.currency)}${amount('Limite do meu grupo (R$, opcional)','budget',old.budget||'',false)}</div>`+`<label>Seu Grupo</label><div class="listchecks">${state.profile.people.map(p=>check(p.name,'person-'+p.id,t?old.people.some(x=>x.id===p.id):true)).join('')}</div><label>Meios de pagamento selecionados</label><div class="listchecks">${accounts().map(a=>check(a.name+' · '+a.type,'method-'+a.id,old.methods.includes(a.id))).join('')||'<small>Cadastre seus cartões na Carteira.</small>'}</div>${check('Dinheiro','cash',t?old.cash!==false:true)}${check('Pix','pix',t?old.pix!==false:true)}`+select('Meio preferencial (opcional)','preferred',[['','Nenhum'],...accounts().map(a=>[a.id,a.name]),['cash','Dinheiro'],['pix','Pix']],old.preferred??'')+field('Observações','notes',old.notes), (d)=>{if(d.start&&d.end&&d.end<d.start)throw Error('A data final deve ser após o início.');let people=[...old.people.filter(p=>!state.profile.people.some(q=>q.id===p.id)),...state.profile.people.filter(p=>d['person-'+p.id]).map(p=>({...p,group:mine}))];let methods=accounts().filter(a=>d['method-'+a.id]).map(a=>a.id);let preferred=d.preferred;if(preferred&&!methods.includes(preferred)&&!(preferred==='cash'&&d.cash)&&!(preferred==='pix'&&d.pix))preferred='';let next={...old,mine,name:d.name.trim(),type:d.type,status:d.status,place:d.place,start:d.start,end:d.end,currency:d.type==='Nacional'?'BRL':d.currency,budget:n(d.budget),notes:d.notes,people,methods,preferred,cash:!!d.cash,pix:!!d.pix,created:old.created??now()};if(!next.name)throw Error('Informe um nome.');commit(s=>upsert(s.trips,next));route('trip/'+next.id)},f=>{const toggle=()=>{f.currency.disabled=f.type.value==='Nacional';if(f.currency.disabled)f.currency.value='BRL';else if(f.currency.value==='BRL')f.currency.value='USD'};f.type.onchange=toggle;toggle()})}
function tripView(t){let x=E.sumTrip(t,state.entries);let tabs=[['overview','Resumo'],['budget','Planejamento'],['daily','Dia a dia'],['groups','Grupos'],['settings','Configuração']];return `<div class="row"><span class="tag">${esc(t.status)}</span><span class="muted">${esc(t.type)} · ${esc(t.place||'Destino a definir')} · ${esc(t.currency)}</span><span class="grow"></span>${btn('Editar viagem','trip-edit',t.id)}</div><div class="tabs">${tabs.map(([k,label])=>btn(label,'tab',k,tab===k?'active':'')).join('')}</div>${({overview:()=>overview(t,x),budget:()=>budget(t),daily:()=>daily(t),groups:()=>groups(t),settings:()=>tripSettings(t)})[tab]()}`}
function overview(t,x){let es=tripEntries(t),unlinked=E.unlinked(t,state.entries);return `<div class="grid summary-grid">${metric('Orçamento planejado',money(x.limit))}${metric('Gasto realizado · meu grupo',money(x.actual))}${metric('Saldo do orçamento',money(x.remaining),x.remaining>=0?'good':'bad')}</div><div class="panel section"><h2>Quanto ainda posso gastar?</h2>${bar(x.limit?x.actual/x.limit*100:0)}<p class="muted">Orçamento menos o gasto realizado. Não é o saldo bancário.</p>${unlinked.length?`<p class="note">${unlinked.length} gasto(s) avulso(s) podem corresponder a previsões existentes. Vincule-os se for o caso; não duplicaremos a previsão.</p>${btn('Conferir gastos','reconcile',t.id)}`:''}<div class="row">${btn('+ Registrar gasto','actual-new',t.id,'primary')}${btn('Planejar','tab','budget')}</div><details><summary>Detalhes do orçamento</summary><div class="rowline"><span class="grow">Previsões ainda abertas</span><strong>${money(x.future)}</strong></div>${unlinked.length?'<p class="subtle">Projeção final indisponível até conferir os gastos avulsos candidatos a vínculo.</p>':`<div class="rowline"><span class="grow">Projeção final (realizado + pendente)</span><strong>${money(x.forecast)}</strong></div>`}${x.unpriced?`<p class="subtle">${x.unpriced} item(ns) ainda sem valor.</p>`:''}</details></div>${categorySummary(t)}${state.movements.some(m=>m.type==='buy'&&m.trip===t.id)?`<div class="panel"><h2>Moeda comprada para esta viagem</h2><p>${money(state.movements.filter(m=>m.type==='buy'&&m.trip===t.id).reduce((a,m)=>a+m.brl,0))} desembolsados na aquisição de saldo. Não somados novamente ao custo da viagem.</p></div>`:''}<details class="panel"><summary>Acerto entre grupos</summary>${settlementView(t)}</details>`}
function categorySummary(t){let es=tripEntries(t), rows=state.categories.map(c=>{let l=es.filter(e=>e.category===c);return [c,l.reduce((a,e)=>a+E.planned(e)*E.share(e,t),0),l.reduce((a,e)=>a+E.realized(e)*E.share(e,t),0)]}).filter(x=>x[1]||x[2]);return `<div class="panel"><h2>Por categoria · meu grupo</h2>${rows.length?rows.map(([c,p,r])=>`<div class="rowline"><div class="grow">${esc(c)}${bar(p?r/p*100:100)}</div><div class="right"><small>${money(p)} previsto</small><br><strong>${money(r)}</strong></div></div>`).join(''):empty('Ainda não há valores registrados.')}</div>`}
function budget(t){let es=tripEntries(t);return `<div class="toolbar"><h2>Despesas planejadas</h2><div class="row">${btn('+ Planejar','plan-menu',t.id,'primary')}<details class="inline-details"><summary>Mais</summary>${btn('Atualizar câmbio','refresh',t.id)}</details></div></div><div class="panel"><div class="row"><div class="grow"><label>Categoria</label><select id="categoryFilter">${options([['all','Todas'],...state.categories],filter)}</select></div></div><p class="subtle">Categorias disponíveis mesmo quando não utilizadas. Planejamento em BRL ou moeda estrangeira.</p>${entryTable(t,es.filter(e=>filter==='all'||e.category===filter))}</div>`}
function entryTable(t,es){return es.length?`<div class="tablewrap"><table><thead><tr><th>Descrição / data</th><th>Previsto (minha parte)</th><th>Realizado (minha parte)</th><th>Ações</th></tr></thead><tbody>${[...es].sort((a,b)=>(a.date||'').localeCompare(b.date||'')).map(e=>`<tr><td><strong>${esc(e.name)}</strong><br><small>${esc(e.category)} · ${esc(e.date||'Geral')}${e.included?' · Incluído':''}${e.protected?' · Protegido':''}${e.envelope?' · Limite diário':''}${e.linkedPlanId?' · Vinculado à previsão':''}${e.plan&&tripEntries(t).some(q=>q.actual&&q.linkedPlanId===e.id)?' · Concluído por gasto vinculado':''}</small>${e.originalPlan?`<br><small>Original: ${money(E.planned({plan:e.originalPlan})*E.share(e,t))}</small>`:''}${e.plan&&e.plan.currency!=='BRL'?`<br><small>${money(e.plan.amount,e.plan.currency)} · ${esc(e.plan.date||'')}</small>`:''}${e.actual&&e.actual.currency!=='BRL'?`<br><small>Pago: ${money(e.actual.amount,e.actual.currency)}</small>`:''}</td><td>${e.plan||e.included?money(E.planned(e)*E.share(e,t)):'—'}</td><td>${e.actual?money(E.realized(e)*E.share(e,t)):e.included?'Incluído':'—'}</td><td><div class="row">${e.envelope?btn('Registrar gasto','actual-envelope',e.id):e.plan&&tripEntries(t).some(q=>q.actual&&q.linkedPlanId===e.id)?btn('Ver gasto vinculado','actual-edit',tripEntries(t).find(q=>q.actual&&q.linkedPlanId===e.id).id):btn(e.actual?'Ver gasto':e.included?'Registrar extra':'Registrar gasto','actual-edit',e.id)}<details class="inline-details"><summary>Mais</summary>${e.plan?btn('Editar previsão','entry-edit',e.id):''}${e.actual&&!e.plan?btn('Vincular ao planejamento','link-entry',e.id):''}${e.actual?.payments?.some(p=>p.method==='Crédito')?btn('Parcelamento','installment',e.id):''}${btn('Excluir','entry-delete',e.id,'danger')}</details></div></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma despesa nesta seleção.')}
function daily(t){let es=tripEntries(t);let days=[...new Set([...E.dates(t.start,t.end),...es.map(e=>e.date).filter(Boolean)])].sort();return `<div class="toolbar"><h2>Dia a dia</h2>${btn('+ Registrar gasto','actual-new',t.id,'primary')}</div>${days.map(d=>{let l=es.filter(e=>e.date===d);let p=l.reduce((a,e)=>a+E.planned(e)*E.share(e,t),0),r=l.reduce((a,e)=>a+E.realized(e)*E.share(e,t),0);return `<div class="panel"><div class="toolbar"><h3>${esc(d.split('-').reverse().join('/'))}</h3><span class="${p-r>=0?'good':'bad'}">${money(r)} / ${money(p)}</span></div>${entryTable(t,l)}${btn('+ Despesa neste dia','entry-day',d)}</div>`}).join('')||empty('Defina as datas ou cadastre despesas com data.')}<div class="panel"><h3>Despesas gerais / sem data</h3>${entryTable(t,es.filter(e=>!e.date))}</div>`}
function groups(t){return `<div class="toolbar"><h2>Participantes e grupos financeiros</h2><div class="row">${btn('+ Grupo','group-new',t.id)}${btn('+ Participante','person-trip',t.id)}</div></div>${t.groups.map(g=>`<div class="panel"><div class="toolbar"><h3>${esc(g.name)} ${g.id===t.mine?'<span class="tag">Meu grupo</span>':''}</h3>${btn('Editar','group-edit',g.id)}</div>${t.people.filter(p=>p.group===g.id).map(p=>`<div class="rowline"><span class="grow">${esc(p.name)} · ${esc(p.kind)}</span>${btn('Editar','person-trip-edit',p.id)}${btn('×','person-trip-delete',p.id,'danger')}</div>`).join('')||'<small>Nenhum participante cadastrado.</small>'}</div>`).join('')}${settlementView(t)}`}
function settlementView(t){let balances=E.settlement(t,state.entries);return `<div class="panel"><h2>Acerto entre grupos</h2>${Object.entries(balances).map(([g,v])=>`<div class="rowline"><span class="grow">${esc(groupName(t,g))}</span><strong class="${v>0?'good':v<0?'bad':''}">${v>0?'A receber ':v<0?'A pagar ':''}${money(Math.abs(v))}</strong></div>`).join('')}<p class="subtle">Diferença entre o total pago e a responsabilidade de cada grupo. Reembolsos podem ser anotados no campo de observações; controle de liquidação fica para próxima versão.</p></div>`}
function tripSettings(t){return `<div class="panel"><h2>Carteira desta viagem</h2>${t.methods.map(a=>`<div class="rowline"><span class="grow">${esc(acctName(a))}</span>${t.preferred===a?'<span class="tag">Preferencial</span>':''}</div>`).join('')}${t.cash!==false?'<div class="rowline">Dinheiro</div>':''}${t.pix!==false?'<div class="rowline">Pix</div>':''}${btn('Alterar seleção','trip-edit',t.id)}</div><div class="panel"><div class="toolbar"><h2>Destinos e moedas por período</h2>${btn('+ Destino','destination',t.id)}</div>${(t.destinations??[]).map(d=>`<div class="rowline"><span class="grow">${esc(d.name)} · ${esc(d.currency)}<br><small>${esc(d.start)} — ${esc(d.end)}</small></span>${btn('Excluir','destination-delete',d.id,'danger')}</div>`).join('')||'<small>A moeda principal será usada em todos os dias.</small>'}</div><div class="panel"><h2>Relatório por pagamento</h2>${paymentReport(t)}</div><div class="panel"><h2>Gerenciar viagem</h2><div class="row">${btn('Exportar Excel','xlsx',t.id)}${btn('Relatório PDF','pdf',t.id)}${btn('Exportar CSV','csv',t.id)}${btn('Excluir viagem','trip-delete',t.id,'danger')}</div></div>`}
function paymentReport(t){let rows={};for(let e of tripEntries(t))for(let p of e.actual?.payments??[])if(p.group===t.mine){let label=p.method+' · '+(p.account?acctName(p.account):'Sem conta');rows[label]=(rows[label]??0)+p.brl}return Object.entries(rows).map(([k,v])=>`<div class="rowline"><span class="grow">${esc(k)}</span><strong>${money(v)}</strong></div>`).join('')||'<small>Sem pagamentos.</small>'}
function splitFields(t,e){return select('Divisão da responsabilidade','split',[['mine','Somente meu grupo'],['equal','Igual entre grupos'],['people','Proporcional às pessoas'],['custom','Personalizada (%)']],e?.split??'mine')+`<div id="shareFields">${t.groups.map(g=>amount(g.name+' (%)','share-'+g.id,e?.shares?.[g.id]??(g.id===t.mine?100:0))).join('')}</div>`}
function getShares(t,d){let s={};if(d.split==='mine')t.groups.forEach(g=>s[g.id]=g.id===t.mine?100:0);if(d.split==='equal')t.groups.forEach(g=>s[g.id]=100/t.groups.length);if(d.split==='people'){let total=t.people.length;if(!total)throw Error('Cadastre participantes antes de dividir por pessoa.');t.groups.forEach(g=>s[g.id]=100*t.people.filter(p=>p.group===g.id).length/total)}if(d.split==='custom'){t.groups.forEach(g=>s[g.id]=n(d['share-'+g.id]));if(Math.abs(Object.values(s).reduce((a,b)=>a+b,0)-100)>.0001)throw Error('A divisão deve somar 100%.')}return s}
function setupSplit(f){let run=()=>{let hide=f.split.value!=='custom';f.querySelector('#shareFields').hidden=hide;f.querySelectorAll('#shareFields input').forEach(i=>i.disabled=hide)};f.split.onchange=run;run()}
function rateFields(p,c,d){return `<div class="formgrid">${select('Moeda original','currency',E.currencies,p?.currency??c)}${select('Câmbio','mode',[['auto','Automático'],['manual','Personalizado']],p?.mode??'auto')}${amount('Valor na moeda selecionada','foreign',p?.amount??'',false)}${amount('Valor em reais','brl',p?E.round(p.amount*p.rate):'',false)}${field('R$ por 1 unidade da moeda','rate',p?.rate??(c==='BRL'?1:''),'number','min="0.0000000001" step="any"')}</div><div class="row" style="margin-top:10px">${btn('Buscar cotação','quote')}<small id="rateInfo">${esc(p?.source??'Cotação de referência; editável em modo personalizado.')}${p?.date?' · '+esc(p.date):''}</small></div>`}
function setupRate(f,original,dateFn){let anchor=original?.anchor??'foreign', info=original?{date:original.date,source:original.source}:null;const update=()=>{let r=n(f.rate.value);if(r<=0)return;if(anchor==='foreign')f.brl.value=f.foreign.value===''?'':E.round(n(f.foreign.value)*r);else f.foreign.value=f.brl.value===''?'':+(n(f.brl.value)/r).toFixed(6)};const lookup=async()=>{let cur=f.currency.value, date=dateFn();f.querySelector('#rateInfo').textContent='Consultando…';try{let q=await quote(cur,date,state.rates);if(f.currency.value!==cur||dateFn()!==date||f.mode.value!=='auto')return;f.rate.value=q.rate;info=q;f.querySelector('#rateInfo').textContent=q.source+' · '+q.date;update()}catch(err){f.querySelector('#rateInfo').textContent=err.message;notify(err.message)}};f.foreign.oninput=()=>{anchor='foreign';update()};f.brl.oninput=()=>{anchor='brl';update()};f.rate.oninput=()=>{info=null;update()};f.querySelector('[data-action=quote]').onclick=ev=>{ev.stopPropagation();f.mode.value='auto';sync();lookup()};const sync=()=>{f.rate.readOnly=f.mode.value==='auto'||f.currency.value==='BRL';if(f.currency.value==='BRL'){f.rate.value=1;info={date:dateFn(),source:'BRL'};update()}};f.mode.onchange=()=>{sync();if(f.mode.value==='auto')lookup()};f.currency.onchange=()=>{info=null;f.rate.value='';sync();if(f.currency.value!=='BRL'&&f.mode.value==='auto')lookup()};f.date?.addEventListener('change',()=>{if(f.mode.value==='auto'){info=null;lookup()}});f.getPrice=()=>{if(f.foreign.value===''&&f.brl.value==='')return null;let rate=n(f.rate.value);if(!(rate>0))throw Error('Informe uma cotação válida.');if(f.mode.value==='auto'&&f.currency.value!=='BRL'&&!info)throw Error('Busque a cotação ou selecione Personalizado.');let val=anchor==='brl'?n(f.brl.value)/rate:n(f.foreign.value);if(!Number.isFinite(val)||val<0)throw Error('Valor inválido.');return {currency:f.currency.value,amount:val,rate,anchor,mode:f.mode.value,date:f.mode.value==='auto'?(info?.date??dateFn()):dateFn(),source:f.mode.value==='manual'?'Personalizado':info?.source??'BRL'}};sync();if(!original&&f.mode.value==='auto'&&f.currency.value!=='BRL')lookup()}
function entryForm(t,e,date=''){let old=e??{id:uid(),trip:t.id,created:now(),name:'',category:'Outros',date,split:'mine',shares:{[t.mine]:100}};modal(e?'Editar planejamento':'Planejar despesa',field('Descrição','name',old.name,'text','required')+`<div class="formgrid">${select('Categoria','category',state.categories,old.category)}${field('Data (vazio = geral)','date',old.date,'date')}</div>${select('Período (opcional)','period',[['','Automático'],['Manhã','Manhã'],['Tarde','Tarde'],['Noite','Noite'],['Outros','Outros']],old.period??'')}`+rateFields(old.plan,currency(t,old.date),old.date)+`<details><summary>Preferência de refeição / quantidade</summary>${mealFields(t)}</details>`+`<details ${t.groups.length>1?'open':''}><summary>Divisão e opções avançadas</summary>`+splitFields(t,old)+check('Despesa protegida / fixa','protected',old.protected)+check('Incluída em outra despesa (custo adicional zero)','included',old.included)+field('Observações','notes',old.notes)+`</details>`,(d,f)=>{let plan=f.getPrice();if(plan&&d.multiply)plan.amount*=Math.max(1,n(d.quantity));if(d.included)plan={currency:'BRL',amount:0,rate:1,anchor:'brl',mode:'auto',date:today(),source:'Incluído'};let v={...old,name:d.name.trim(),category:d.category,date:d.date,period:d.period,plan,split:d.split,shares:getShares(t,d),protected:!!d.protected,included:!!d.included,notes:d.notes};if(old.plan&&!old.originalPlan)v.originalPlan=structuredClone(old.plan);commit(s=>upsert(s.entries,v))},f=>{setupSplit(f);setupRate(f,old.plan,()=>today());setupMeal(f)})}
function actualForm(t,e,seed){let old=e??seed??{id:uid(),trip:t.id,created:now(),name:'',category:'Outros',date:today(),shares:{[t.mine]:100},split:'mine'};let a=old.actual,p=a?.payments?.[0];let def=t.preferred, preferred=state.accounts.find(x=>x.id===def);let initMethod=p?.method??preferred?.type??(def==='pix'?'Pix':def==='cash'?'Dinheiro':'Crédito');let cur=a?.currency??currency(t,old.date||today());let price=a?{currency:a.currency,amount:a.amount,rate:a.rate,anchor:a.anchor,mode:a.mode,date:a.rateDate,source:a.source}:null;modal('Registrar despesa realizada',field('Descrição','name',old.name,'text','required')+`<div class="formgrid">${select('Categoria','category',state.categories,old.category)}${field('Data do gasto','date',a?.date||(old.date||today()),'date','required')}</div>`+rateFields(price,cur,old.date)+(!old.plan?select('Vincular a uma previsão (opcional)','linkedPlanId',[['','Gasto avulso'],...linkCandidates(t,old).map(q=>[q.id,q.name+' · '+money(E.planned(q)*E.share(q,t))])],old.linkedPlanId??''):'')+`<details ${t.groups.length>1?'open':''}><summary>Divisão entre grupos</summary>`+splitFields(t,old)+select('Quem pagou','payer',t.groups.map(g=>[g.id,g.name]),p?.group??t.mine)+`</details>`+select('Forma de pagamento','method',methods,initMethod)+`<label for="f-account">Cartão / conta</label><select name="account" id="f-account"></select>${check('Mostrar também cartões fora da seleção','allAccounts',false)}<div id="balanceFields">${check('Descontar do saldo cadastrado (custo médio)','track',p?.track??false)}<div class="formgrid">${select('Moeda debitada','debitCurrency',E.currencies,p?.debitCurrency??cur)}${amount('Valor efetivamente debitado','debitAmount',p?.debitAmount??'',false)}</div><p class="subtle" id="balanceInfo"></p></div><details ${a?.payments?.length>1?'open':''}><summary>Mais opções de pagamento</summary>${check('Adicionar segundo pagamento','second',a?.payments?.length>1)}<div id="secondFields">${select('Segundo pagador','payer2',t.groups.map(g=>[g.id,g.name]),a?.payments?.[1]?.group??t.mine)}${select('Segunda forma de pagamento','method2',methods,a?.payments?.[1]?.method??'Pix')}${select('Segunda conta (opcional)','account2',[['','Sem conta'],...state.accounts.map(x=>[x.id,x.name+' · '+x.type])],a?.payments?.[1]?.account??'')}${amount('Valor da segunda parte em reais','part2',a?.payments?.[1]?.brl??'',false)}<p class="subtle">O saldo da segunda conta não é movimentado nesta versão.</p></div></details>`+field('Observações','notes',old.notes),(d,f)=>{let pr=f.getPrice();if(!pr)throw Error('Informe o valor pago.');let brl=E.round(pr.amount*pr.rate),actual={currency:pr.currency,amount:pr.amount,rate:pr.rate,anchor:pr.anchor,mode:pr.mode,rateDate:pr.date,source:pr.source,date:d.date,created:a?.created??now(),brl,payments:[]};let first={group:d.payer,method:d.method,account:d.account||'',brl,track:!!d.track,debitCurrency:d.debitCurrency,debitAmount:n(d.debitAmount)||(d.debitCurrency===pr.currency?pr.amount:0)};if(first.track&&first.debitCurrency===pr.currency&&!d.debitAmount)first.debitAmount=pr.amount;if(first.track){if(first.group!==t.mine)throw Error('A carteira global pertence ao meu grupo.');if(!first.account||!(first.debitAmount>0)||!['Débito','Dinheiro','Pix'].includes(first.method))throw Error('Selecione a conta e valor debitado para controlar o saldo.');if(d.second)throw Error('Para pagamento dividido, desative a baixa de saldo ou registre despesas separadas.');actual.payments=[first];let test={...old,actual};let others=state.entries.filter(x=>x.id!==old.id);let l=E.ledger(state.movements,[...others,test],true);let cost=l.costs[old.id+'-0'];if(cost===undefined)throw Error('Custo da baixa indisponível.');actual.referenceBRL=brl;actual.brl=cost;first.brl=cost;actual.source='Custo médio da carteira'}if(d.second){let part=n(d.part2);if(part<=0||part>=actual.brl)throw Error('O segundo pagamento deve ser menor que o total e maior que zero.');first.brl=E.round(actual.brl-part);let acc=state.accounts.find(x=>x.id===d.account2);if(acc&&acc.type!==d.method2&&d.method2!=='Pix')throw Error('A segunda conta deve corresponder à forma de pagamento.');actual.payments=[first,{group:d.payer2,method:d.method2,account:d.account2,brl:part,track:false}]}else actual.payments=[first];let v={...old,name:d.name.trim(),category:d.category,date:old.plan?old.date:d.date,split:d.split,shares:getShares(t,d),actual,linkedPlanId:old.plan?undefined:(d.linkedPlanId||undefined),checkedUnlinked:old.checkedUnlinked,notes:d.notes,included:false};commit(s=>upsert(s.entries,v))},f=>{setupSplit(f);setupRate(f,price,()=>f.date.value||today());const refreshAccounts=()=>{let prev=f.account.value||p?.account||def||'';let all=state.accounts.filter(x=>x.type===f.method.value||(f.method.value==='Pix'&&x.type==='Débito'));let selected=all.filter(x=>f.allAccounts.checked||t.methods.includes(x.id)||x.id===p?.account||x.type==='Dinheiro'&&!x.archived);f.account.innerHTML=options([['','Sem conta específica'],...selected.map(x=>[x.id,x.name+(x.archived?' (arquivado)':'')])],prev);if(!selected.some(x=>x.id===prev)&&selected.length===1)f.account.value=selected[0].id;refreshBalance()};const refreshBalance=()=>{let allowed=['Débito','Dinheiro','Pix'].includes(f.method.value)&&!!f.account.value;f.querySelector('#balanceFields').hidden=!allowed;if(!allowed)f.track.checked=false;let slots=E.ledger(state.movements,state.entries.filter(x=>x.id!==old.id)).slots.filter(x=>x.account===f.account.value);f.querySelector('#balanceInfo').textContent=slots.map(x=>money(x.balance,x.currency)+' disponível').join(' · ')||'Sem saldo cadastrado.';if(!p&&f.account.value&&slots.length){let slot=slots.find(x=>x.currency===f.currency.value)??slots[0];f.debitCurrency.value=slot.currency;if(f.currency.value===slot.currency){f.track.checked=true;f.debitAmount.value=f.foreign.value}}};f.method.onchange=f.allAccounts.onchange=refreshAccounts;f.account.onchange=refreshBalance;let toggle=()=>{f.querySelector('#secondFields').hidden=!f.second.checked;f.querySelectorAll('#secondFields input,#secondFields select').forEach(i=>i.disabled=!f.second.checked)};f.second.onchange=toggle;toggle();refreshAccounts();f.foreign.addEventListener('input',()=>{if(f.track.checked&&f.debitCurrency.value===f.currency.value)f.debitAmount.value=f.foreign.value});f.brl.addEventListener('input',()=>{if(f.track.checked&&f.debitCurrency.value===f.currency.value)f.debitAmount.value=f.foreign.value});f.currency.addEventListener('change',refreshBalance)})}
function dailyBudget(t){modal('Criar despesas diárias',select('Categoria','category',state.categories,'Alimentação geral')+field('Descrição','name','Alimentação','text','required')+`<div class="formgrid">${field('Primeiro dia','start',t.start??today(),'date','required')}${field('Último dia','end',t.end??today(),'date','required')}${amount('Valor diário do meu grupo (R$)','brl','')}</div>`+mealFields(t)+check('Ignorar dias que já possuem esta categoria','skip',true),(d)=>{let days=E.dates(d.start,d.end);if(!days.length||days.length>366)throw Error('Selecione de 1 a 366 dias.');commit(s=>{for(let date of days){if(d.skip&&s.entries.some(e=>e.trip===t.id&&e.date===date&&e.category===d.category))continue;if(s.entries.some(e=>e.trip===t.id&&e.date===date&&e.envelope&&(e.category===d.category||e.category==='Alimentação geral'&&E.food.includes(d.category)||d.category==='Alimentação geral'&&E.food.includes(e.category))))throw Error('Já existe limite diário sobreposto. Edite o existente.');s.entries.push({id:uid(),trip:t.id,created:now(),name:d.name,category:d.category,date,split:'mine',envelope:true,shares:{[t.mine]:100},plan:{currency:'BRL',amount:n(d.brl)*(d.multiply?Math.max(1,n(d.quantity)):1),rate:1,anchor:'brl',mode:'auto',date:today(),source:'BRL'}})}})},f=>setupMeal(f))}
function stayForm(t){modal('Cadastrar hospedagem',field('Nome da hospedagem','name','','text','required')+`<div class="formgrid">${field('Check-in','start',t.start??today(),'date','required')}${field('Check-out','end',t.end??today(),'date','required')}</div>`+rateFields(null,currency(t,t.start),today())+splitFields(t,null)+check('Café da manhã incluído','breakfast',true)+check('Despesa protegida','protected',true)+field('Observações','notes',''),(d,f)=>{let nights=E.dates(d.start,d.end).slice(1);if(!nights.length||nights.length>366)throw Error('Confira as datas de hospedagem.');let plan=f.getPrice(),stayId=uid(),shares=getShares(t,d);commit(s=>{s.entries.push({id:stayId,trip:t.id,created:now(),name:d.name,category:'Hospedagem',date:'',plan,split:d.split,shares,protected:!!d.protected,notes:d.notes,stay:{start:d.start,end:d.end,breakfast:!!d.breakfast}});for(let date of d.breakfast?nights:[]){let existing=s.entries.find(e=>e.trip===t.id&&e.date===date&&e.category==='Café da manhã'&&!e.actual);if(existing){existing.beforeIncluded=existing.plan;existing.included=true;existing.stayId=stayId;existing.plan={currency:'BRL',amount:0,rate:1,anchor:'brl',mode:'auto',date:today(),source:'Incluído'}}else s.entries.push({id:uid(),trip:t.id,created:now(),name:'Café da manhã · '+d.name,category:'Café da manhã',date,split:'mine',shares:{[t.mine]:100},included:true,stayId,generated:true,plan:{currency:'BRL',amount:0,rate:1,anchor:'brl',mode:'auto',date:today(),source:'Incluído'}})}})},f=>{setupSplit(f);setupRate(f,null,()=>today())})}
function wallet(){let slots=E.ledger(state.movements,state.entries).slots;return `<div class="toolbar"><h2>Meios de pagamento</h2>${btn('+ Cartão / conta','account-new','','primary')}${btn('+ Dinheiro em espécie','cash-new')}</div><div class="grid">${state.accounts.map(a=>`<div class="panel"><span class="tag">${esc(a.type)} ${a.archived?'· Arquivado':''}</span><h2 style="margin-top:16px">${esc(a.name)}</h2><small>${esc(a.institution||'Conta / carteira')} · ${esc(a.currency)}</small>${slots.filter(s=>s.account===a.id).map(s=>`<div class="rowline"><div class="grow"><small>Saldo ${esc(s.currency)}</small><div class="large">${money(s.balance,s.currency)}</div><small>Custo restante: ${money(s.cost)} · ${s.balance>0?'R$ '+(s.cost/s.balance).toLocaleString('pt-BR',{maximumFractionDigits:8})+' / '+s.currency:'—'}</small></div></div>`).join('')}<div class="row" style="margin-top:12px">${btn('Editar','account-edit',a.id)}${btn(a.archived?'Reativar':'Arquivar','account-archive',a.id)}${['Débito','Dinheiro'].includes(a.type)&&!a.archived?btn('+ Saldo','buy',a.id,'primary'):''}</div></div>`).join('')||empty('Cadastre seus cartões, contas internacionais e carteiras em dinheiro.')}</div>${savingsView()}<div class="panel"><div class="toolbar"><h2>Movimentações globais</h2><div class="row">${btn('+ Compra / saldo inicial','buy')}${btn('Transferência / saque','transfer')}</div></div><p class="subtle">Compras de moeda e transferências não entram como despesas de viagem. Cadastre taxas separadamente se não estiverem incluídas no custo de aquisição.</p>${state.movements.length?state.movements.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(m=>`<div class="rowline"><div class="grow"><strong>${m.type==='buy'?'Compra / entrada':'Transferência'}${m.paymentMethod?' · '+esc(m.paymentMethod):''}</strong><br><small>${esc(m.date)} · ${esc(acctName(m.account))}${m.type==='transfer'?' → '+esc(acctName(m.target)):''}${m.trip?' · '+esc(state.trips.find(t=>t.id===m.trip)?.name??'Viagem removida'):''}${m.origin?' · '+esc(m.origin):''}</small></div><div class="right">${money(m.amount,m.currency)}<br><small>${m.type==='buy'?money(m.brl):money(m.received,m.targetCurrency)}</small></div>${btn('×','move-delete',m.id,'danger')}</div>`).join(''):empty('Sem movimentações.')}</div>`}
function accountForm(a,preset){let old=a??preset??{id:uid(),name:'',type:'Débito',currency:'Multimoeda'};modal('Cartão ou conta',field('Nome / apelido','name',old.name,'text','required')+select('Forma de pagamento','type',methods,old.type)+select('Moeda da conta','currency',['Multimoeda',...E.currencies],old.currency)+field('Instituição (opcional)','institution',old.institution)+field('Observações (sem dados sensíveis)','notes',old.notes),(d)=>commit(s=>upsert(s.accounts,{...old,...d,name:d.name.trim()})))}
function movementForm(type,account){let eligible=accounts().filter(a=>['Débito','Dinheiro'].includes(a.type));if(!eligible.length){notify('Cadastre uma conta ou carteira de débito/dinheiro primeiro.');return}let a=eligible.find(x=>x.id===account)??eligible[0];let c=a.currency==='Multimoeda'?'USD':a.currency;modal(type==='buy'?'Comprar moeda / registrar saldo inicial':'Transferência ou saque',select('Conta de origem (ou destino da compra)','account',eligible.map(a=>[a.id,a.name]),a.id)+field('Data','date',today(),'date','required')+select('Moeda','currency',E.currencies,c)+amount(type==='buy'?'Valor recebido na conta':'Valor retirado da origem','amount','')+(type==='buy'?amount('Valor desembolsado em reais, incluindo taxas','brl','')+select('Forma de pagamento da compra','paymentMethod',methods,'Pix')+select('Viagem (opcional)','trip',[['','Sem viagem'],...state.trips.map(t=>[t.id,t.name])],'')+field('Origem / observação (opcional)','origin',''):select('Conta de destino','target',eligible.map(a=>[a.id,a.name]),eligible[1]?.id??a.id)+select('Moeda recebida','targetCurrency',E.currencies,c)+amount('Valor recebido no destino','received',''))+`<p class="note">${type==='buy'?'Use o desembolso efetivo para calcular o custo médio. Para saldo inicial, informe seu custo de aquisição conhecido ou estimado.':'O custo médio da origem acompanha o saldo transferido. Uma taxa cobrada separadamente deve ser registrada como despesa.'}</p>`,d=>{if(n(d.amount)<=0||type==='buy'&&n(d.brl)<=0||type==='transfer'&&n(d.received)<=0)throw Error('Informe valores positivos.');if(type==='transfer'&&d.account===d.target&&d.currency===d.targetCurrency)throw Error('Origem e destino não podem ser iguais.');commit(s=>s.movements.push({id:uid(),created:now(),type,account:d.account,date:d.date,currency:d.currency,amount:n(d.amount),brl:n(d.brl),target:d.target,targetCurrency:d.targetCurrency,received:n(d.received),paymentMethod:d.paymentMethod,trip:d.trip,origin:d.origin}))})}
function profile(){let p=state.profile;return `<div class="panel"><div class="toolbar"><div><h2>${esc(p.name||'Meu perfil')}</h2><p class="muted">${esc(p.home)} · BRL</p></div>${btn('Editar perfil','profile-edit')}</div><p>${esc(p.notes||'Configure seu perfil e participantes habituais.')}</p></div><div class="panel"><div class="toolbar"><h2>Seu Grupo</h2>${btn('+ Pessoa','person-profile')}</div>${p.people.map(x=>`<div class="rowline"><span class="grow">${esc(x.name)} · ${esc(x.kind)}</span>${btn('Editar','person-profile-edit',x.id)}${x.id!=='self'?btn('×','person-profile-delete',x.id,'danger'):''}</div>`).join('')}</div><div class="panel"><div class="toolbar"><h2>Preferências de refeições</h2>${btn('Editar parâmetros','params')}</div><p class="subtle">Valor de referência por pessoa, em reais. Não é um limite de gasto.</p>${Object.entries(p.mealPrefs??{}).map(([k,v])=>`<div class="rowline"><span class="grow">${esc(k)}</span><strong>${money(v)}</strong></div>`).join('')||'<small>Nenhum parâmetro definido.</small>'}</div><div class="panel"><div class="toolbar"><h2>Categorias</h2>${btn('+ Categoria','category-new')}</div><div class="row">${state.categories.map(c=>`<span class="tag">${esc(c)}</span>`).join('')}</div></div>${cloudPanel()}<div class="panel"><h2>Backup</h2><p class="subtle">Faça uma cópia dos seus dados antes de mudanças importantes.</p><div class="row">${btn('Exportar backup','backup','','primary')}${btn('Importar backup','import')}${btn('Exportar CSV','csv-all')}</div><p class="subtle">v1.3.1</p></div>`}
function profileForm(){let p=state.profile;modal('Configurar meu perfil',field('Nome','name',p.name,'text','required')+field('País de residência','home',p.home)+field('Observações','notes',p.notes),(d)=>commit(s=>Object.assign(s.profile,d)))}
function personForm(t,p){let old=p??{id:uid(),name:'',kind:'Adulto',group:t?.mine};modal('Participante',field('Nome','name',old.name,'text','required')+select('Tipo','kind',['Adulto','Criança'],old.kind)+(t?select('Grupo financeiro','group',t.groups.map(g=>[g.id,g.name]),old.group):''),d=>commit(s=>{let list=t?s.trips.find(x=>x.id===t.id).people:s.profile.people;upsert(list,{...old,...d})}))}
function groupForm(t,g){let old=g??{id:uid(),name:''};modal('Grupo financeiro',field('Nome do grupo','name',old.name,'text','required'),d=>commit(s=>upsert(s.trips.find(x=>x.id===t.id).groups,{...old,name:d.name})))}
function destinationForm(t){modal('Adicionar destino',field('Cidade / país','name','','text','required')+select('Moeda','currency',E.currencies,t.currency)+field('Início','start',t.start,'date','required')+field('Fim','end',t.end,'date','required'),d=>{if(d.end<d.start)throw Error('Confira as datas.');if((t.destinations??[]).some(x=>x.start<=d.end&&x.end>=d.start))throw Error('Período sobreposto a outro destino.');commit(s=>{let tr=s.trips.find(x=>x.id===t.id);(tr.destinations??=[]).push({id:uid(),...d})})})}
function analysisView(){let rows=E.analysis(state.trips,state.entries,analysisType);let trips=state.trips.filter(t=>t.status==='Concluída'&&(analysisType==='all'||t.type===analysisType));let total=trips.reduce((a,t)=>a+E.sumTrip(t,state.entries).actual,0);let dated=trips.filter(t=>E.dates(t.start,t.end).length);let days=dated.reduce((a,t)=>a+E.dates(t.start,t.end).length,0);let foodTotal=E.analysis(dated,state.entries,analysisType).filter(r=>E.food.includes(r.category)).reduce((a,r)=>a+r.total,0);return `<div class="panel"><div class="toolbar"><h2>Meu padrão real de consumo</h2><select id="analysisType" style="width:auto">${options([['all','Todas'],['Nacional','Nacional'],['Internacional','Internacional']],analysisType)}</select></div><p class="muted">Somente despesas realizadas de viagens concluídas, relativas ao meu grupo. Refeições incluídas não entram na média por compra.</p><div class="grid">${metric('Viagens concluídas',String(trips.length))}${metric('Gasto total',money(total))}${metric('Gasto médio por viagem',trips.length?money(total/trips.length):'—')}${metric('Alimentação por dia de viagem',days?money(foodTotal/days):'—')}</div></div><div class="panel"><h2>Consumo por categoria</h2>${rows.length?`<div class="tablewrap"><table><thead><tr><th>Categoria</th><th>Média por lançamento</th><th>Total</th><th>Amostra</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.category)}</td><td>${money(r.avg)}</td><td>${money(r.total)}</td><td>${r.count} gastos · ${r.trips} viagem(ns)</td></tr>`).join('')}</tbody></table></div>`:empty('Conclua uma viagem com despesas reais para criar seu histórico.')}<p class="subtle">A média por lançamento não é uma média por pessoa ou refeição quando um lançamento reúne vários itens. Histórico pequeno não permite conclusões confiáveis.</p></div><div class="panel"><h2>Histórico de viagens</h2>${trips.map(t=>{let x=E.sumTrip(t,state.entries);return `<div class="rowline"><div class="grow"><strong>${esc(t.name)}</strong><br><small>${esc(t.type)} · ${E.dates(t.start,t.end).length} dias</small></div><strong>${money(x.actual)}</strong>${btn('Abrir','trip-open',t.id)}</div>`}).join('')||'<small>Sem histórico.</small>'}</div>`}
function download(name,content,type){let url=URL.createObjectURL(new Blob([content],{type}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function csv(trip){let cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';let rows=[['Viagem','Categoria','Descrição','Data','Moeda prevista','Valor previsto original','Previsto BRL grupo','Moeda realizada','Valor realizado original','Realizado BRL grupo','Pagamento','Cotação realizada','Fonte câmbio']];for(let e of state.entries.filter(e=>!trip||e.trip===trip.id)){let t=state.trips.find(t=>t.id===e.trip);rows.push([t.name,e.category,e.name,e.date,e.plan?.currency,e.plan?.amount,e.plan?E.round(E.planned(e)*E.share(e,t)):'',e.actual?.currency,e.actual?.amount,e.actual?E.round(E.realized(e)*E.share(e,t)):'',e.actual?.payments.map(p=>p.method+' '+acctName(p.account)).join(' / '),e.actual?.rate,e.actual?.source])}download('travel-planner-despesas.csv','\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
$('#importFile').onchange=async ev=>{let file=ev.target.files[0];if(!file)return;try{let next=E.validateBackup(JSON.parse(await file.text()));if(confirm('Restaurar este backup e substituir TODOS os dados atuais? Exporte o atual antes se necessário.')){store.save(next);state=next;storedAtRender=canonical(store.load());loadFailed=false;route('home');notify('Backup restaurado.');if(cloud.session)cloud.schedule()}}catch(err){notify('Não foi possível restaurar: '+err.message)}finally{ev.target.value=''}};
async function refresh(t){let next=structuredClone(state);let snapshot=state;let count=0,fail=0;notify('Atualizando cotações…');for(let e of next.entries.filter(e=>e.trip===t.id&&!e.actual&&e.plan?.currency!=='BRL'&&e.plan?.mode==='auto'&&e.plan?.anchor==='foreign')){try{let q=await quote(e.plan.currency,today(),next.rates);if(!e.originalPlan)e.originalPlan=structuredClone(e.plan);Object.assign(e.plan,q);count++}catch{fail++}}if(state!==snapshot){notify('Os dados mudaram durante a consulta. Repita a atualização.');return}commit(s=>{s.entries=next.entries;s.rates=next.rates});notify(`${count} atualizada(s); ${fail} indisponível(is).`)}
function rebalance(t){let d=E.dynamic(t,state.entries);if(!d.count||d.available<0){notify('Não há itens flexíveis suficientes para o ajuste.');return}let ratio=d.plannedFlexible>0?Math.max(0,d.available/d.plannedFlexible):1;modal('Readequar orçamento',`<p>Há ${d.count} despesas flexíveis com previsão total de ${money(d.plannedFlexible)}. Disponível após compromissos: ${money(d.available)}.</p>${check('Somente reduzir (não gastar a economia)','onlyReduce',true)}<p class="note">O ajuste é proporcional ao valor de cada item. O orçamento original permanece registrado.</p>`,data=>{let factor=data.onlyReduce?Math.min(1,ratio):ratio;commit(s=>{let tr=s.trips.find(x=>x.id===t.id);if(!tr.budget)tr.budget=E.sumTrip(t,state.entries).limit;for(let e of s.entries.filter(x=>d.ids.includes(x.id))){e.originalPlan??=structuredClone(e.plan);if(e.envelope&&E.share(e,t)>0){let pending=E.pending(e,s.entries,t),used=E.planned(e)*E.share(e,t)-pending;e.plan.amount=(used+pending*factor)/(e.plan.rate*E.share(e,t))}else e.plan.amount*=factor}})})}
function removeEntry(s,e){if(e.stay){for(let x of s.entries.filter(x=>x.stayId===e.id)){if(x.actual){delete x.stayId;continue}if(x.generated)s.entries=s.entries.filter(y=>y.id!==x.id);else{x.included=false;x.plan=x.beforeIncluded??null;delete x.stayId;delete x.beforeIncluded}}}s.entries=s.entries.filter(x=>x.id!==e.id);s.installments=(s.installments??[]).filter(x=>x.entry!==e.id);for(let x of s.entries)if(x.linkedPlanId===e.id)delete x.linkedPlanId}
document.addEventListener('change',ev=>{if(ev.target.id==='categoryFilter'){filter=ev.target.value;render()}if(ev.target.id==='analysisType'){analysisType=ev.target.value;render()}});
document.addEventListener('click',async ev=>{let b=ev.target.closest('[data-action]');if(!b)return;let a=b.dataset.action,i=b.dataset.id,t=activeTrip()??state.trips.find(t=>t.id===i),e=state.entries.find(e=>e.id===i),acct=state.accounts.find(a=>a.id===i);try{switch(a){case 'cloud-login':cloudLogin();break;case 'cloud-sync':await cloud.sync();break;case 'cloud-logout':if(confirm('Sair da nuvem? Os dados continuarão neste dispositivo.')){await cloud.logout();render()}break;case 'cloud-local':case 'cloud-remote':await chooseCloud(a==='cloud-local'?'local':'remote');break;case 'cloud-recovery':case 'cloud-recovery-remote':{let raw=localStorage.getItem(a==='cloud-recovery'?'ptp-cloud-recovery-v1':'ptp-cloud-recovery-remote-v1');if(raw)download('ptp-recuperacao-'+today()+'.json',raw,'application/json');else notify('Nenhuma cópia de recuperação.');break;}case 'trip-new':tripForm();break;case 'trip-edit':tripForm(t);break;case 'trip-open':route('trip/'+i);break;case 'tab':tab=i;render();break;case 'profile-edit':profileForm();break;case 'person-profile':personForm();break;case 'person-profile-edit':personForm(null,state.profile.people.find(p=>p.id===i));break;case 'person-profile-delete':if(confirm('Retirar pessoa do perfil? As viagens existentes não mudam.'))commit(s=>s.profile.people=s.profile.people.filter(p=>p.id!==i));break;case 'params':modal('Preferências de refeições por pessoa',mealKinds.map((c,j)=>amount(c+' (R$)','p'+j,state.profile.mealPrefs?.[c]??'',false)).join(''),d=>commit(s=>{s.profile.mealPrefs=Object.fromEntries(mealKinds.map((c,j)=>[c,d['p'+j]]).filter(([,v])=>v!=='').map(([c,v])=>[c,n(v)]))}));break;case 'category-new':modal('Nova categoria',field('Nome','name','','text','required'),d=>commit(s=>{if(s.categories.includes(d.name))throw Error('Categoria já existe.');s.categories.push(d.name)}));break;case 'account-new':accountForm();break;case 'cash-new':accountForm(null,{id:uid(),name:'Dinheiro em espécie',type:'Dinheiro',currency:'Multimoeda'});break;case 'account-edit':accountForm(acct);break;case 'account-archive':commit(s=>{s.accounts.find(x=>x.id===i).archived=!acct.archived});break;case 'buy':movementForm('buy',i);break;case 'transfer':movementForm('transfer',i);break;case 'move-delete':if(confirm('Excluir movimentação?'))commit(s=>s.movements=s.movements.filter(m=>m.id!==i));break;case 'plan-menu':planMenu(t);break;case 'reconcile':reconcile(t);break;case 'link-entry':linkEntry(t,e);break;case 'saving-add':savingForm(i);break;case 'saving-del':if(confirm('Excluir aporte?'))commit(s=>s.savings=s.savings.filter(x=>x.id!==i));break;case 'installment':installmentForm(e);break;case 'installment-del':if(confirm('Remover parcelamento da poupança?'))commit(s=>s.installments=s.installments.filter(x=>x.id!==i));break;case 'xlsx':download('Personal-Travel-Planner.xlsx',excelReport(t,state.entries),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');break;case 'pdf':printReport(t);break;case 'entry-new':entryForm(t);break;case 'entry-day':entryForm(t,null,i);break;case 'entry-edit':entryForm(t,e);break;case 'entry-delete':if(confirm('Excluir despesa prevista e realizada?'))commit(s=>removeEntry(s,e));break;case 'actual-new':actualForm(t);break;case 'actual-edit':actualForm(t,e);break;case 'actual-envelope':actualForm(t,null,{id:uid(),trip:t.id,created:now(),name:'',category:e.category,date:e.date,shares:{[t.mine]:100},split:'mine'});break;case 'daily-budget':dailyBudget(t);break;case 'stay':stayForm(t);break;case 'group-new':groupForm(t);break;case 'group-edit':groupForm(t,t.groups.find(g=>g.id===i));break;case 'person-trip':personForm(t);break;case 'person-trip-edit':personForm(t,t.people.find(p=>p.id===i));break;case 'person-trip-delete':if(confirm('Retirar participante? As divisões existentes não serão alteradas.'))commit(s=>{let tr=s.trips.find(x=>x.id===t.id);tr.people=tr.people.filter(p=>p.id!==i)});break;case 'destination':destinationForm(t);break;case 'destination-delete':commit(s=>{let tr=s.trips.find(x=>x.id===t.id);tr.destinations=tr.destinations.filter(d=>d.id!==i)});break;case 'trip-delete':if(confirm('Excluir toda a viagem e suas despesas? As compras de moeda continuarão na carteira.')){commit(s=>{s.entries=s.entries.filter(x=>x.trip!==t.id);s.trips=s.trips.filter(x=>x.id!==t.id);s.installments=(s.installments??[]).filter(x=>x.trip!==t.id)});route('trips')}break;case 'backup':download('travel-planner-backup-'+today()+'.json',JSON.stringify(state,null,2),'application/json');notify('Backup exportado.');break;case 'import':$('#importFile').click();break;case 'csv':csv(t);break;case 'csv-all':csv();break;case 'refresh':await refresh(t);break;case 'rebalance':rebalance(t);break;case 'quote':break}}catch(err){notify(err.message)}});
const mealKinds=['Econômica','Experiência gastronômica','Alto nível'];
function mealFields(t){let count=Math.max(1,t.people.filter(p=>p.group===t.mine).length);return select('Referência de refeição (opcional)','mealPreset',[['','Sem referência'],...mealKinds.filter(k=>state.profile.mealPrefs?.[k]!=null).map(k=>[k,k+' · '+money(state.profile.mealPrefs[k])+' / pessoa'])],'')+check('Multiplicar o valor por pessoas','multiply',false)+amount('Quantidade de pessoas','quantity',count)}
function setupMeal(f){if(!f.mealPreset)return;f.mealPreset.onchange=()=>{let v=state.profile.mealPrefs?.[f.mealPreset.value];if(v==null)return;f.brl.value=v;f.brl.dispatchEvent(new Event('input'));};}
function planMenu(t){modal('O que deseja planejar?',`<div class="stack">${btn('Despesa única','entry-new',t.id,'primary')}${btn('Limite diário','daily-budget',t.id)}${btn('Hospedagem','stay',t.id)}</div>`,()=>{});$('#modalForm [type=submit]').hidden=true;$('#fields').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>$('#modal').close(),{once:true}));}
function linkCandidates(t,e){let es=tripEntries(t);return es.filter(q=>q.plan&&!q.envelope&&!q.included&&!q.actual&&q.id!==e.id&&!es.some(x=>x.actual&&x.linkedPlanId===q.id&&x.id!==e.id))}
function linkEntry(t,e){modal('Vincular gasto à previsão',`<p>${esc(e.name)} · ${money(E.realized(e)*E.share(e,t))}</p>`+select('Previsão correspondente','target',[['','Não corresponde a uma previsão'],...linkCandidates(t,e).map(q=>[q.id,q.name+' · '+money(E.planned(q)*E.share(q,t))])],e.linkedPlanId??''),d=>commit(s=>{let x=s.entries.find(x=>x.id===e.id);x.linkedPlanId=d.target||undefined;x.checkedUnlinked=!d.target}))}
function reconcile(t){let es=E.unlinked(t,state.entries);modal('Conferir gastos avulsos',`<p>Se já havia previsão para um gasto, vincule-o. Nenhuma despesa será apagada.</p>${es.map(e=>`<div class="rowline"><span class="grow">${esc(e.name)} · ${money(E.realized(e)*E.share(e,t))}</span>${btn('Conferir','link-entry',e.id)}</div>`).join('')}`,()=>{});$('#modalForm [type=submit]').hidden=true;$('#fields').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>$('#modal').close(),{once:true}));}
function savingsView(){let month=today().slice(0,7);return `<div class="panel"><h2>Poupança Viagem</h2><p class="subtle">Controle virtual: aportes informados menos parcelas previstas até o mês atual. Nenhum dinheiro é movimentado no banco.</p><div class="grid">${['Nacional','Internacional'].map(type=>{let r=E.savingsSummary(state,type,month);return `<div class="metric"><small>${type}</small><strong>${money(r.balance)}</strong><p class="subtle">Aportes acumulados: ${money(r.deposits)} · Parcelas até ${month}: ${money(r.deducted)}</p><p>Neste mês: ${money(r.monthDeposit)} aporte − ${money(r.monthDeducted)} parcelas = <strong>${money(r.monthNet)}</strong></p><p>Próximos meses: ${money(r.future)} comprometidos</p>${btn('+ Aporte mensal','saving-add',type,'primary')}</div>`}).join('')}</div><details><summary>Aportes e parcelas</summary>${(state.savings??[]).map(x=>`<div class="rowline"><span class="grow">${esc(x.type)} · ${esc(x.month)}</span>${money(x.amount)}${btn('Excluir','saving-del',x.id)}</div>`).join('')}${(state.installments??[]).map(x=>{let e=state.entries.find(e=>e.id===x.entry);return `<div class="rowline"><span class="grow">${esc(e?.name??'Despesa')} · ${x.count}x · início ${esc(x.start)}</span>${money(x.total)}${btn('Editar','installment',x.entry)}${btn('Excluir','installment-del',x.id)}</div>`}).join('')}</details><p class="subtle">Para parcelar, abra uma despesa realizada no crédito → Mais → Parcelamento.</p></div>`}
function savingForm(type){let month=today().slice(0,7);let existing=(state.savings??[]).find(x=>x.type===type&&x.month===month);modal('Aporte mensal · '+type,field('Mês','month',month,'month','required')+amount('Valor destinado à viagem (R$)','amount',existing?.amount??''),d=>commit(s=>{s.savings??=[];let prev=s.savings.find(x=>x.type===type&&x.month===d.month);upsert(s.savings,{id:prev?.id??uid(),type,month:d.month,amount:n(d.amount)})}))}
function installmentForm(e){if(!e?.actual)throw Error('Registre o gasto primeiro.');let t=state.trips.find(t=>t.id===e.trip),old=(state.installments??[]).find(x=>x.entry===e.id);let max=E.round(Math.min(E.realized(e)*E.share(e,t),e.actual.payments.filter(p=>p.group===t.mine&&p.method==='Crédito').reduce((a,p)=>a+p.brl,0)));modal('Parcelamento na Poupança Viagem',`<p class="note">O custo integral continua na viagem. Somente o fluxo mensal da poupança é parcelado.</p>`+amount('Total de responsabilidade do meu grupo no crédito (R$)','total',old?.total??max)+field('Número de parcelas','count',old?.count??1,'number','min="1" max="120" step="1" required')+field('Mês da primeira parcela','start',old?.start??today().slice(0,7),'month','required'),d=>{if(n(d.total)>max||n(d.total)<=0||!Number.isInteger(n(d.count))||n(d.count)<1||n(d.count)>120)throw Error('Confira valor e parcelas.');commit(s=>{s.installments??=[];upsert(s.installments,{id:old?.id??uid(),entry:e.id,trip:t.id,type:t.type,total:n(d.total),count:n(d.count),start:d.start})})})}
function printReport(t){let x=E.sumTrip(t,state.entries);let w=window.open('','_blank');if(!w){notify('Permita abrir uma nova janela para imprimir.');return}let rows=reportRows(t,state.entries);w.document.write(`<html lang="pt-BR"><head><title>${esc(t.name)} · Relatório</title><style>body{font:14px Arial;margin:32px;color:#172033}h1{font-size:25px}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:left}th{background:#eaf0f7}button{padding:10px} @media print{button{display:none}tr{break-inside:avoid}}</style></head><body><h1>Personal Travel Planner</h1><h2>${esc(t.name)}</h2><p>Orçamento: ${money(x.limit)} | Realizado: ${money(x.actual)} | Saldo: ${money(x.remaining)}</p><p>Valores do meu grupo em BRL.</p><table><thead><tr><th>Data</th><th>Categoria / descrição</th><th>Planejado</th><th>Realizado</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.date||'Geral')}</td><td>${esc(r.category)} — ${esc(r.name)}</td><td>${r.plan==null?'—':money(r.plan)}</td><td>${r.actual==null?'—':money(r.actual)}</td></tr>`).join('')}</tbody></table><p><button onclick="window.print()">Imprimir / Salvar como PDF</button></p></body></html>`);w.document.close()}
render();if(cloud.session)cloud.sync();setInterval(()=>{if(!document.hidden&&cloud.session)cloud.sync()},20000);window.addEventListener('online',()=>cloud.sync());window.addEventListener('focus',()=>cloud.sync());document.addEventListener('visibilitychange',()=>{if(!document.hidden)cloud.sync()});window.addEventListener('storage',ev=>{if(ev.key==='travel-planner-v1'){if(!$('#modal').open&&!loadFailed){state=E.validateBackup(store.load());storedAtRender=canonical(state);render()}else notify('Dados alterados em outra aba. Feche e recarregue antes de editar.')}});if('serviceWorker'in navigator&&['https:','http:'].includes(location.protocol))navigator.serviceWorker.register('./sw.js').catch(()=>{});

function cloudChoices(){let p=cloud.pending;if(!p||!['seed','missing','conflict'].includes(p.action))return '';return `<p class="note">${p.action==='conflict'?'Existem versões diferentes dos seus dados.':p.action==='missing'?'A cópia da nuvem não foi encontrada.':'A nuvem ainda está vazia.'}</p><div class="row">${btn('Usar este aparelho','cloud-local','','primary')}${p.remote?btn('Usar nuvem','cloud-remote'):''}</div>`}
function cloudPanel(){return `<div class="panel"><h2>Sincronização</h2><p class="subtle" id="cloudStatus">${esc(cloud.last||(cloud.session?'Conectado':'Somente neste aparelho'))}</p>${!cloud.configured?'<p class="subtle">Finalize a configuração da nuvem e volte aqui.</p>':cloud.session?`<p class="subtle">Conta: ${esc(cloud.session.user.email||'Conectada')}</p><div class="row">${btn('Sincronizar','cloud-sync','','primary')}${btn('Sair','cloud-logout')}</div>`:btn('Entrar','cloud-login','','primary')}<div id="cloudChoices">${cloudChoices()}</div>${localStorage.getItem('ptp-cloud-recovery-v1')?btn('Backup local','cloud-recovery'):''}${localStorage.getItem('ptp-cloud-recovery-remote-v1')?btn('Backup da nuvem','cloud-recovery-remote'):''}<p class="subtle">Sem internet, o app continua funcionando e sincroniza depois.</p></div>`}
function cloudLogin(){modal('Entrar',field('E-mail','email','','email','required autocomplete="username"')+field('Senha','password','','password','required autocomplete="current-password"'),async d=>{await cloud.login(d.email,d.password);render();setTimeout(()=>cloud.sync(),500)})}
async function chooseCloud(choice){let p=cloud.pending;if(!p||cloud.busy)throw Error('Aguarde e sincronize novamente.');if(!confirm('Será necessário escolher uma versão. A outra não será mesclada. Confirma guardar as cópias e continuar?'))return;localStorage.setItem('ptp-cloud-recovery-v1',JSON.stringify(p.local));download('ptp-local-antes-'+today()+'.json',JSON.stringify(p.local,null,2),'application/json');if(p.remote){localStorage.setItem('ptp-cloud-recovery-remote-v1',JSON.stringify(p.remote));download('ptp-nuvem-antes-'+today()+'.json',JSON.stringify(p.remote,null,2),'application/json')}await cloud.sync(choice,p);render()}
